/* BURKAB — bildirim okumak işi başlatmaz veya kapatmaz. */
(()=>{'use strict';const c=window.BURKAB_WORK_CONTEXT;if(!c)return;let items=[],lastUser='',busy=false,seen=null,soundEnabled=false;const el=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const style=document.createElement('style');style.textContent='#workButton{position:fixed;bottom:18px;left:18px;z-index:1800;border:0;border-radius:24px;background:#f5c400;color:#171717;padding:13px 20px;font-weight:800;box-shadow:0 4px 20px #0004;cursor:pointer}#workPanel{position:fixed;inset:12px 12px 75px auto;width:480px;max-width:calc(100vw - 24px);z-index:1850;background:#f3f5f7;color:#18232c;box-shadow:0 14px 60px #0006;border-radius:14px;overflow:auto;font:14px Arial}#workPanel *{box-sizing:border-box}#workPanel header{position:sticky;top:0;background:#18232c;border-top:5px solid #f5c400;color:white;padding:14px;z-index:1}#workPanel button{padding:10px;border:1px solid #bcc7d0;border-radius:7px;cursor:pointer;margin:3px;background:white;color:#18232c}#workPanel article{margin:12px;background:white;border-radius:10px;padding:14px;border-left:5px solid #e5b900;overflow-wrap:anywhere}#workPanel h3{font-size:16px;margin:6px 0}#workPanel p{white-space:pre-wrap}#workPanel small{color:#536471}#workError{padding:8px 14px;color:#b12b16}';document.head.append(style);
const button=document.createElement('button');button.id='workButton';button.hidden=true;button.textContent='İş bildirimleri';document.body.append(button);const panel=document.createElement('section');panel.id='workPanel';panel.hidden=true;panel.innerHTML='<header><b>İş bildirimleri</b><div><button data-action="refresh">Yenile</button><button data-action="sound" aria-pressed="false">Sesi aç</button><button data-action="test-sound">Sesi dene</button><button data-action="close">Kapat</button></div><label><input id="workHistory" type="checkbox"> Sonuçlanan kayıtları göster</label></header><div id="workSoundStatus" role="status" style="padding:8px 14px;font-size:12px"></div><div id="workError" role="alert"></div><div id="workItems"></div>';document.body.append(panel);

const notificationAudio=new Audio('data:audio/mpeg;base64,');notificationAudio.preload='auto';notificationAudio.volume=1;
function soundState(){const b=panel.querySelector('[data-action="sound"]');b.textContent=soundEnabled?'Sesi kapat':'Sesi aç';b.setAttribute('aria-pressed',String(soundEnabled));}
function stopSound(){notificationAudio.pause();try{notificationAudio.currentTime=0;}catch(_){} }
async function playSound(){try{stopSound();await notificationAudio.play();el('workSoundStatus').textContent=soundEnabled?'Bildirim sesi açık. Yeni iş geldiğinde bu ses çalar.':'Test sesi çalıyor. Bildirimler için Sesi aç düğmesine basın.';return true;}catch(e){soundEnabled=false;soundState();el('workSoundStatus').textContent=e.name==='NotAllowedError'?'Tarayıcı sesi engelledi. Sesi aç düğmesine tekrar basın.':'Ses çalınamadı. Cihazın ve tarayıcı sekmesinin sesini kontrol edin.';return false;}}

function userKey(){const u=c.user();return u?.token&&u.username?u.username+'|'+u.token:'';}
function render(){const list=items.filter(x=>el('workHistory').checked?!x.open:x.open);button.textContent='İş bildirimleri · '+items.filter(x=>x.open).length+' açık / '+items.filter(x=>x.open&&!x.read).length+' yeni';el('workItems').innerHTML=list.map(x=>'<article><small>'+esc(x.type)+' · '+esc(x.status)+(x.read?' · Okundu':' · Yeni')+'</small><h3>'+esc(x.machine||'Makine belirtilmedi')+'</h3><p>'+esc(x.title)+'</p>'+(x.owner?'<p>İşi alan: '+esc(x.owner)+(x.start?' · '+esc(x.start):'')+'</p>':'')+(x.result?'<p>Sonuç: '+esc(x.result)+'</p>':'')+'<button data-action="read" data-key="'+esc(x.key)+'">Okudum</button>'+(x.open&&c.open?'<button data-action="open" data-key="'+esc(x.key)+'">İşi aç</button>':'')+'</article>').join('')||'<article>Bu görünümde kayıt yok.</article>';}
async function refresh(){const key=userKey();if(!key){button.hidden=true;panel.hidden=true;items=[];seen=null;lastUser='';soundEnabled=false;stopSound();soundState();return;}button.hidden=false;if(key!==lastUser){items=[];seen=null;soundEnabled=false;stopSound();soundState();lastUser=key;render();}if(busy||document.hidden)return;busy=true;try{const r=await c.request({action:'getWorkInboxV3',context:c.name});if(key!==userKey())return;if(!r?.ok)throw Error(r?.error||'Bildirimler alınamadı.');const next=r.items||[],open=next.filter(x=>x.open).map(x=>x.key);if(seen&&soundEnabled&&open.some(k=>!seen.has(k)))await playSound();seen=new Set(open);items=next;el('workError').textContent='';render();}catch(e){el('workError').textContent=e.message+' Son liste korunuyor.';}finally{busy=false;}}
button.onclick=()=>{panel.hidden=!panel.hidden;if(!panel.hidden)refresh();};el('workHistory').onchange=render;panel.onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='close'){panel.hidden=true;return;}if(a==='refresh'){refresh();return;}if(a==='sound'){if(soundEnabled){soundEnabled=false;stopSound();soundState();el('workSoundStatus').textContent='Bildirim sesi kapalı.';}else{soundEnabled=true;soundState();await playSound();}return;}if(a==='test-sound'){await playSound();return;}const x=items.find(x=>x.key===b.dataset.key);if(!x)return;b.disabled=true;try{const r=await c.request({action:'markWorkReadV3',context:c.name,key:x.key});if(!r?.ok)throw Error(r?.error||'Okundu kaydedilemedi.');x.read=true;render();if(a==='open'){await c.open(x);panel.hidden=true;}}catch(e){el('workError').textContent=e.message;}finally{b.disabled=false;}};window.BurkWork={refresh,show:()=>{panel.hidden=false;refresh();}};setInterval(refresh,30000);setInterval(()=>{if(userKey()!==lastUser)refresh();},1500);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});refresh();})();
